import { CopyButton } from "@/registry/erbium/blocks/copy-button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/registry/erbium/ui/card";
import { Icon } from "@/registry/erbium/ui/icon";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/registry/erbium/ui/input-group";
import { QRCode, QRCodeDownload, QRCodeImage } from "@/registry/erbium/ui/qr-code";

const link = "https://ui.erbium.app/invite/9f8a7b6c";

export default function QRCodeShareLinkExample() {
  return (
    <Card className="w-80">
      <CardHeader>
        <CardTitle>Invite your team</CardTitle>
        <CardDescription>Scan the code or send the link.</CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col items-center gap-group">
        <QRCode value={link} className="w-full">
          <QRCodeImage aria-label="Scan to open the invite link" />
          <InputGroup>
            <InputGroupInput aria-label="Invite link" dir="ltr" readOnly value={link} />
            <InputGroupAddon align="inline-end">
              <CopyButton
                value={link}
                aria-label="Copy invite link"
                render={<InputGroupButton variant="embedded" size="icon-xs" />}
              />
              <QRCodeDownload
                aria-label="Download QR code"
                fileName="invite"
                render={<InputGroupButton variant="embedded" size="icon-xs" />}
              >
                <Icon name="download-01" />
              </QRCodeDownload>
            </InputGroupAddon>
          </InputGroup>
        </QRCode>
      </CardContent>
    </Card>
  );
}

import Example from "../examples/qr-code-share-link";

const Variant = () => <Example />;

export default Variant;
